    self.assertEqual(compare("1.9.0", "1.10.0"), -1)
    self.assertEqual(compare("10.0.0", "2.0.0"), 1)
    self.assertEqual(compare("2.0.0", "10.0.0"), -1)

def test_leading_zeros(self):
